@@ -27,13 +27,57 @@
 // hist[b] = number of i < n with (in[i] & 255) == b for b < 256. Neither out nor
 // hist is zeroed by the caller. n is any size from 0 to 20'000'000; the sums
 // never overflow int64.
+
+// Tunable parameters for performance optimization
+constexpr size_t BLOCK_SIZE = 4096;      // Process data in blocks for prefetching
+constexpr int NUM_SUBHISTS = 8;          // Number of private sub-histograms to break dependency chains
+constexpr int UNROLL_FACTOR = 4;         // Loop unrolling factor
+
 extern "C" void scan_and_histogram(const int64_t* in, int64_t* out, size_t n, uint64_t* hist) {
-    for (int b = 0; b < 256; ++b) hist[b] = 0;
+    // Initialize private sub-histograms with uint32_t (sufficient for n < 2^32)
+    uint32_t priv_hist[NUM_SUBHISTS][256];
+    for (int p = 0; p < NUM_SUBHISTS; ++p) {
+        for (int b = 0; b < 256; ++b) {
+            priv_hist[p][b] = 0;
+        }
+    }
+
     int64_t sum = 0;
-    for (size_t i = 0; i < n; ++i) {
-        sum += in[i];
-        out[i] = sum;
-        hist[in[i] & 255]++;
+    size_t i = 0;
+
+    // Process in blocks to allow prefetching and reduce register pressure
+    while (i < n) {
+        size_t end = i + BLOCK_SIZE;
+        if (end > n) end = n;
+
+        // Prefetch next block's input data
+        if (end < n) {
+            __builtin_prefetch(in + end, 0, 3);
+        }
+
+        // Unrolled loop over block
+        size_t j = i;
+        for (; j < end; j += UNROLL_FACTOR) {
+            for (int u = 0; u < UNROLL_FACTOR; ++u) {
+                size_t idx = j + u;
+                if (idx >= end) break;
+                int64_t val = in[idx];
+                sum += val;
+                out[idx] = sum;
+                uint8_t bin = (uint8_t)(val & 255);
+                priv_hist[idx & (NUM_SUBHISTS - 1)][bin]++;
+            }
+        }
+        i = end;
+    }
+
+    // Merge private histograms into the final histogram
+    for (int b = 0; b < 256; ++b) {
+        uint64_t total = 0;
+        for (int p = 0; p < NUM_SUBHISTS; ++p) {
+            total += priv_hist[p][b];
+        }
+        hist[b] = total;
     }
 }
